package com.example.yuejie;

import android.app.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.graphics.*;import android.os.*;import org.json.*;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;

/** Optional fonts only: fixtures live in this test APK, never in the shipping APK or production library. */
public final class FontChecks extends Instrumentation {
 int checks;Bundle options;
 public void onCreate(Bundle args){super.onCreate(args);options=args;start();}
 void ok(boolean yes,String label){if(!yes)throw new AssertionError(label);checks++;Bundle b=new Bundle();b.putString("stream","PASS "+label+"\n");sendStatus(0,b);}
 static final class Isolated extends ContextWrapper {
  final File root;final String prefix;
  Isolated(Context c,String name){super(c);prefix="font-check-"+name;root=new File(c.getCacheDir(),prefix);root.mkdirs();}
  public Context getApplicationContext(){return this;}public File getFilesDir(){File f=new File(root,"files");f.mkdirs();return f;}
  public File getDatabasePath(String name){return new File(root,name);}
  public SQLiteDatabase openOrCreateDatabase(String name,int mode,SQLiteDatabase.CursorFactory factory){return SQLiteDatabase.openOrCreateDatabase(getDatabasePath(name),factory);}
  public SQLiteDatabase openOrCreateDatabase(String name,int mode,SQLiteDatabase.CursorFactory factory,android.database.DatabaseErrorHandler handler){return SQLiteDatabase.openOrCreateDatabase(getDatabasePath(name).getPath(),factory,handler);}
  public SharedPreferences getSharedPreferences(String name,int mode){return super.getSharedPreferences(prefix+"-"+name,mode);}
 }
 byte[] fixture(String file)throws Exception{try(InputStream in=getContext().getAssets().open(file)){return ProtocolCrypto.read(in);}}
 HttpURLConnection fixtureConnection(String url,byte[] data,int status,int failAfter,CountDownLatch entered,CountDownLatch release)throws Exception{return new HttpURLConnection(new URL(url)){
  public void connect(){}public void disconnect(){}public boolean usingProxy(){return false;}public int getResponseCode(){return status;}public long getContentLengthLong(){return data.length;}
  public InputStream getInputStream(){return new InputStream(){int index;boolean held;
   public int read()throws IOException{byte[] b=new byte[1];return read(b,0,1)==-1?-1:b[0]&255;}
   public int read(byte[] b,int off,int len)throws IOException{if(!held&&entered!=null&&index>262144){held=true;entered.countDown();try{if(!release.await(10,TimeUnit.SECONDS))throw new IOException("fixture wait expired");}catch(InterruptedException e){throw new IOException(e);}}if(failAfter>=0&&index>=failAfter)throw new IOException("连接中断，请重试");if(index==data.length)return -1;int n=Math.min(Math.min(len,8192),data.length-index);System.arraycopy(data,index,b,off,n);index+=n;return n;}
  };}
 };}
 void complete(ReaderFonts fonts,String id)throws Exception{complete(fonts,id,20000);}
 void complete(ReaderFonts fonts,String id,long timeout)throws Exception{long until=SystemClock.elapsedRealtime()+timeout;while(fonts.state(id).downloading&&SystemClock.elapsedRealtime()<until)Thread.sleep(20);if(fonts.state(id).downloading)throw new AssertionError("download timeout "+id);waitForIdleSync();}
 void manager()throws Exception{
  Context c=new Isolated(getTargetContext(),"manager-"+System.nanoTime());ReaderFonts fonts=ReaderFonts.get(c);
  try{
   ReaderSettings clean=new ReaderSettings(c);ok(clean.fontFamily.equals("system")&&clean.typeface().equals(Typeface.DEFAULT),"new installation defaults to system font");
   for(boolean serif:new boolean[]{false,true}){SharedPreferences prefs=c.getSharedPreferences("ReaderActivity",0);prefs.edit().clear().putBoolean("reader_v2",true).putBoolean("serif",serif).putInt("font",37).putInt("line_spacing_percent",62).putInt("font_weight_amount",80).putString("page_turn_mode","simulation").putBoolean("night",true).putBoolean("volume_keys",false).putFloat("brightness",.42f).commit();ReaderSettings migrated=new ReaderSettings(c);ok(migrated.fontFamily.equals("system"),"legacy "+(serif?"serif":"sans")+" falls back when optional font absent");ok(migrated.font==37&&migrated.spacingPercent==62&&migrated.fontWeight==80&&migrated.night&&!migrated.volumeKeys&&Math.abs(migrated.brightness-.42f)<.001&&migrated.pageTurnMode==PageTurnMode.SIMULATION,"upgrade preserves all other reader settings");}
   ReaderSettings setting=new ReaderSettings(c);ok(!setting.selectFont("sans")&&setting.fontFamily.equals("system"),"missing font cannot be selected");
   byte[] sans=fixture("reader-body.ttf");fonts.source=url->fixtureConnection(url,sans,503,-1,null,null);fonts.download("sans");complete(fonts,"sans");ok(!fonts.available("sans")&&!fonts.state("sans").error.isEmpty(),"HTTP failure offers retry and never installs font");
   fonts.source=url->fixtureConnection(url,sans,200,32768,null,null);fonts.download("sans");complete(fonts,"sans");ok(!fonts.available("sans")&&!fonts.file("sans").exists(),"interrupted stream never becomes available");
   byte[] corrupt=sans.clone();corrupt[100]^=1;fonts.source=url->fixtureConnection(url,corrupt,200,-1,null,null);fonts.download("sans");complete(fonts,"sans");ok(!fonts.available("sans")&&fonts.state("sans").error.contains("校验"),"same-size corrupt file fails SHA-256 verification");
   CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);fonts.source=url->fixtureConnection(url,sans,200,-1,entered,release);fonts.download("sans");ok(entered.await(10,TimeUnit.SECONDS),"download reaches partial progress");ok(fonts.state("sans").received>0&&fonts.state("sans").received<fonts.state("sans").font.size&&!fonts.available("sans"),"partial progress visible without allowing selection");release.countDown();complete(fonts,"sans");ok(fonts.available("sans")&&fonts.state("sans").received==sans.length,"retry installs complete verified sans");
   ok(setting.fontFamily.equals("system"),"download alone does not switch current reading font");ok(setting.selectFont("sans"),"verified sans can be explicitly selected");setting.save();String sansKey=setting.fontKey;
   ReaderFonts offline=new ReaderFonts(c);try{offline.source=url->{throw new IOException("offline");};ok(offline.available("sans")&&offline.face("sans")!=Typeface.DEFAULT,"verified font reloads from persistent files while offline");}finally{offline.io.shutdownNow();}
   byte[] serif=fixture("reader-serif.ttf");fonts.source=url->fixtureConnection(url,serif,200,-1,null,null);fonts.download("serif");complete(fonts,"serif");ok(fonts.available("serif")&&setting.selectFont("serif"),"serif downloads and becomes selectable");setting.save();ok(!setting.fontKey.equals(sansKey),"layout cache separates optional font identities");
   ReaderSettings restart=new ReaderSettings(c);ok(restart.fontFamily.equals("serif"),"font choice persists across settings reload");
   fonts.delete("serif");ReaderSettings fallback=new ReaderSettings(c);ok(fallback.fontFamily.equals("system")&&!fonts.file("serif").exists(),"deleting active font removes disk file and falls back to system");
   fonts.delete("sans");CountDownLatch enteredCancel=new CountDownLatch(1),releaseCancel=new CountDownLatch(1);fonts.source=url->fixtureConnection(url,sans,200,-1,enteredCancel,releaseCancel);fonts.download("sans");ok(enteredCancel.await(10,TimeUnit.SECONDS),"cancel test reaches in-flight download");fonts.delete("sans");releaseCancel.countDown();fonts.io.submit(()->{}).get(10,TimeUnit.SECONDS);ok(!fonts.available("sans")&&!fonts.file("sans").exists(),"delete during download cannot reinstall cancelled font");
   fonts.source=url->fixtureConnection(url,sans,200,-1,null,null);fonts.download("sans");complete(fonts,"sans");ok(fonts.available("sans"),"cancelled download can be retried");
   try(RandomAccessFile file=new RandomAccessFile(fonts.file("sans"),"rw")){file.seek(100);int value=file.read();file.seek(100);file.write(value^1);}
   ReaderFonts diskCheck=new ReaderFonts(c);try{ok(!diskCheck.available("sans"),"startup integrity check rejects changed local font");}finally{diskCheck.io.shutdownNow();}
  }finally{fonts.io.shutdownNow();}
 }
 void upgrade()throws Exception{Context c=getTargetContext();ReaderSettings s=new ReaderSettings(c);ok(s.fontFamily.equals("system")&&s.typeface().equals(Typeface.DEFAULT),"actual v0.26 upgrade falls back from bundled serif to system");ok(s.font==37&&s.spacingPercent==62&&s.fontWeight==80&&s.night&&!s.volumeKeys&&Math.abs(s.brightness-.42f)<.001&&s.pageTurnMode==PageTurnMode.SIMULATION,"actual APK upgrade preserves other settings");LocalLibrary library=new LocalLibrary(c);String book="999991234567893";ok(library.contains(book)&&library.progress(book).optInt("offset")==923&&library.bookmark(book,"995",923),"actual APK upgrade preserves shelf, progress and bookmark");SQLiteDatabase db=library.getWritableDatabase();db.beginTransaction();try{for(String table:new String[]{"books","progress","directories","chapters","bookmarks","library_updates","sync_state","sync_outbox","sync_deferred"})db.delete(table,(table.equals("books")?"id":"book")+"=?",new String[]{book});db.setTransactionSuccessful();}finally{db.endTransaction();}library.close();}
 void live()throws Exception{Context c=new Isolated(getTargetContext(),"live-"+System.nanoTime());ReaderFonts fonts=ReaderFonts.get(c);try{for(String id:fonts.ids()){fonts.download(id);complete(fonts,id,180000);ok(fonts.available(id),"live HTTPS independent font download "+id+": "+fonts.state(id).error);ReaderFonts.verify(fonts.file(id),fonts.state(id).font);}fonts.delete("sans");fonts.delete("serif");}finally{fonts.io.shutdownNow();}}
 ReaderActivity reader;
 void ui(Runnable action){runOnMainSync(action);waitForIdleSync();}
 void ready()throws Exception{long until=SystemClock.elapsedRealtime()+20000;while(SystemClock.elapsedRealtime()<until){boolean[] yes={false};ui(()->yes[0]=reader!=null&&!reader.busy&&reader.surface.frame!=null);if(yes[0])return;Thread.sleep(30);}throw new AssertionError("reader layout timeout");}
 void shot(String name)throws Exception{waitForIdleSync();SystemClock.sleep(250);Bitmap image=getUiAutomation().takeScreenshot();File folder=new File(getTargetContext().getExternalFilesDir(null),"font-checks");folder.mkdirs();try(OutputStream out=new FileOutputStream(new File(folder,name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
 String progressVersion(LocalLibrary library,String book){try(Cursor cursor=library.getReadableDatabase().rawQuery("SELECT op FROM sync_state WHERE kind='progress' AND book=?",new String[]{book})){return cursor.moveToFirst()?cursor.getString(0):"";}}
 void reader()throws Exception{
  if(!Build.FINGERPRINT.contains("generic")&&!Build.MODEL.contains("sdk"))throw new AssertionError("UI fixtures require isolated emulator");
  Context c=getTargetContext();LocalLibrary library=new LocalLibrary(c);String book="999991234567892";if(!library.books(false).isEmpty()||LibrarySync.pending(library.getReadableDatabase()).length()!=0)throw new AssertionError("UI fixtures require empty app library");
  SharedPreferences prefs=c.getSharedPreferences("ReaderActivity",0);Map<String,?> previous=new HashMap<>(prefs.getAll());SyncEngine engine=SyncEngine.get(c);SyncEngine.Remote original=engine.remote;ReaderFonts fonts=ReaderFonts.get(c);ReaderFonts.Source source=fonts.source;
  engine.remote=(path,body)->{if(path.endsWith("time"))return new JSONObject().put("server_time",System.currentTimeMillis());JSONArray ack=new JSONArray(),ops=body.getJSONArray("operations");for(int i=0;i<ops.length();i++)ack.put(ops.getJSONObject(i).getString("id"));return new JSONObject().put("cursor",0).put("ack",ack).put("changes",new JSONArray()).put("more",false);};
  try{
   fonts.delete("sans");fonts.delete("serif");prefs.edit().clear().putBoolean("reader_v2",true).putBoolean("serif",true).putInt("font",24).putInt("line_spacing_percent",45).putBoolean("paragraph_comments",false).commit();
   JSONObject raw=new JSONObject().put("book_id",book).put("book_name","Font position fixture").put("author","Test");library.add(new Book(raw));JSONArray dir=new JSONArray().put(new JSONObject().put("id","994").put("title","第一章"));library.directory(book,dir);String text=String.join("\n\n",Collections.nCopies(150,"系统字体与下载字体切换后，应保留同一章节和原文字符偏移，不把排版变化当成新的阅读进度。"));library.chapter(book,"994",new JSONObject().put("id","994").put("title","第一章").put("text",text).put("paragraphs",new JSONArray().put(text)));library.progress(book,"994",823,0,1,"第一章");c.getSharedPreferences("page_metadata",0).edit().putString(book,new JSONArray().put(new JSONObject().put("id","994").put("word_count",text.length())).toString()).commit();
   reader=(ReaderActivity)startActivitySync(new Intent(c,ReaderActivity.class).putExtra("book_id",book).putExtra("book_name","Font position fixture").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ui(()->{reader.directorySource=(b,f)->dir;reader.source=(b,ch)->library.chapter(b,ch);});ready();
   engine.schedule(0);engine.worker.submit(()->{}).get(10,TimeUnit.SECONDS);
   int anchor=reader.anchor;String version=progressVersion(library,book);ok(anchor==823&&reader.settings.fontFamily.equals("system"),"legacy reader opens at original character offset using system font");
   ui(()->{reader.showSettings();reader.showFontPicker();});shot("01-fonts-system");
   byte[] sans=fixture("reader-body.ttf");fonts.source=url->fixtureConnection(url,sans,503,-1,null,null);fonts.download("sans");complete(fonts,"sans");shot("02-fonts-failed-retry");
   CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);fonts.source=url->fixtureConnection(url,sans,200,-1,entered,release);fonts.download("sans");ok(entered.await(10,TimeUnit.SECONDS),"reader font UI receives progress");waitForIdleSync();shot("03-fonts-progress");release.countDown();complete(fonts,"sans");
   byte[] serif=fixture("reader-serif.ttf");fonts.source=url->fixtureConnection(url,serif,200,-1,null,null);fonts.download("serif");complete(fonts,"serif");shot("04-fonts-downloaded");
   String systemKey=reader.settings.fontKey;
   for(String id:new String[]{"sans","serif","system"}){ui(()->reader.selectReaderFont(id));ready();ReaderPaginator.Page page=reader.surface.frame.layout.pages.get(reader.surface.frame.pageIndex);ok(reader.chapter.optString("id").equals("994")&&reader.anchor==anchor&&page.start<=anchor&&anchor<page.end,"font switch "+id+" keeps chapter, anchor and visible containing page");ok(version.equals(progressVersion(library,book)),"font switch "+id+" does not create synchronized progress operation");if(!id.equals("system"))ok(!systemKey.equals(reader.settings.fontKey),"font switch invalidates page-count layout cache "+id);}
   ui(()->reader.selectReaderFont("sans"));ready();fonts.source=url->{throw new IOException("offline");};ActivityMonitor monitor=addMonitor(ReaderActivity.class.getName(),null,false);ui(()->reader.recreate());ReaderActivity next=(ReaderActivity)monitor.waitForActivityWithTimeout(10000);removeMonitor(monitor);if(next==null)throw new AssertionError("reader recreation missing");reader=next;ui(()->{reader.directorySource=(b,f)->dir;reader.source=(b,ch)->library.chapter(b,ch);});ready();ok(reader.anchor==anchor&&reader.settings.fontFamily.equals("sans"),"offline reader recreation retains downloaded font and position");
   ui(()->{reader.showFontPicker();reader.deleteReaderFont("sans");});ready();ok(reader.settings.fontFamily.equals("system")&&reader.anchor==anchor&&version.equals(progressVersion(library,book)),"delete active font reflows to system without progress change");shot("05-fonts-deleted");
  }finally{
   if(reader!=null)ui(()->reader.finish());fonts.delete("sans");fonts.delete("serif");fonts.source=source;SQLiteDatabase db=library.getWritableDatabase();db.beginTransaction();try{for(String table:new String[]{"books","progress","directories","chapters","bookmarks","library_updates","sync_state","sync_outbox","sync_deferred"})db.delete(table,(table.equals("books")?"id":"book")+"=?",new String[]{book});db.setTransactionSuccessful();}finally{db.endTransaction();}c.getSharedPreferences("page_metadata",0).edit().remove(book).commit();SharedPreferences.Editor edit=prefs.edit().clear();for(Map.Entry<String,?> e:previous.entrySet()){Object v=e.getValue();if(v instanceof String)edit.putString(e.getKey(),(String)v);else if(v instanceof Integer)edit.putInt(e.getKey(),(Integer)v);else if(v instanceof Boolean)edit.putBoolean(e.getKey(),(Boolean)v);else if(v instanceof Float)edit.putFloat(e.getKey(),(Float)v);else if(v instanceof Long)edit.putLong(e.getKey(),(Long)v);}edit.commit();engine.remote=original;SyncEngine.activeBook="";library.close();
  }
 }
 public void onStart(){try{if("true".equals(options.getString("upgrade")))upgrade();manager();if("true".equals(options.getString("reader")))reader();if("true".equals(options.getString("live")))live();Bundle b=new Bundle();b.putString("stream","PASS "+checks+" font checks");finish(0,b);}catch(Throwable e){Bundle b=new Bundle();b.putString("stream","FAIL "+android.util.Log.getStackTraceString(e));finish(1,b);}}
}
